   793  int _sc_parse_atr(sc_reader_t *reader)
   794  {
   795          u8 *p = reader->atr.value;
   796          int atr_len = (int) reader->atr.len;
   797          int n_hist, x;
   798          int tx[4] = {-1, -1, -1, -1};
   799          int i, FI, DI;
   800          const int Fi_table[] = {
   801                  372, 372, 558, 744, 1116, 1488, 1860, -1,
   802                  -1, 512, 768, 1024, 1536, 2048, -1, -1 };
   803          const int f_table[] = {
   804                  40, 50, 60, 80, 120, 160, 200, -1,
   805                  -1, 50, 75, 100, 150, 200, -1, -1 };
   806          const int Di_table[] = {
   807                  -1, 1, 2, 4, 8, 16, 32, -1,
   808                  12, 20, -1, -1, -1, -1, -1, -1 };
   809
   810          reader->atr_info.hist_bytes_len = 0;
   811          reader->atr_info.hist_bytes = NULL;
   812
   813          if (atr_len == 0) {
   814                  sc_log(reader->ctx, "empty ATR - card not present?\n");
   815                  return SC_ERROR_INTERNAL;
   816          }
   817
   818          if (p[0] != 0x3B && p[0] != 0x3F) {
   819                  sc_log(reader->ctx, "invalid sync byte in ATR: 0x%02X\n", p[0]);
   820                  return SC_ERROR_INTERNAL;
   821          }
   822          n_hist = p[1] & 0x0F;
   823          x = p[1] >> 4;
   824          p += 2;
   825          atr_len -= 2;
   826          for (i = 0; i < 4 && atr_len > 0; i++) {
   827                  if (x & (1 << i)) {
   828                          tx[i] = *p;
   829                          p++;
   830                          atr_len--;
   831                  } else
   832                          tx[i] = -1;
   833          }
   834          if (tx[0] >= 0) {
   835                  reader->atr_info.FI = FI = tx[0] >> 4;
   836                  reader->atr_info.DI = DI = tx[0] & 0x0F;
   837                  reader->atr_info.Fi = Fi_table[FI];
   838                  reader->atr_info.f = f_table[FI];
   839                  reader->atr_info.Di = Di_table[DI];
   840          } else {
   841                  reader->atr_info.Fi = -1;
   842                  reader->atr_info.f = -1;
   843                  reader->atr_info.Di = -1;
   844          }
   845          if (tx[2] >= 0)
   846                  reader->atr_info.N = tx[3];
   847          else
   848                  reader->atr_info.N = -1;
   849          while (tx[3] > 0 && tx[3] & 0xF0 && atr_len > 0) {
   850                  x = tx[3] >> 4;
   851                  for (i = 0; i < 4 && atr_len > 0; i++) {
   852                          if (x & (1 << i)) {
   853                                  tx[i] = *p;
   854                                  p++;
   855                                  atr_len--;
   856                          } else
   857                                  tx[i] = -1;
   858                  }
   859          }
   860          if (atr_len <= 0)
   861                  return SC_SUCCESS;
   862          if (n_hist > atr_len)
   863                  n_hist = atr_len;
   864          reader->atr_info.hist_bytes_len = n_hist;
   865          reader->atr_info.hist_bytes = p;
   866          return SC_SUCCESS;
   867  }
